SELECT jsonb_build_object(
'tournament',(SELECT jsonb_build_object('id',id,'name',name,'year',"seasonYear",'status',status) FROM "Tournament" WHERE id='tournament-2026'),
'entries',(SELECT jsonb_agg(jsonb_build_object('teamId',t.id,'name',t.name,'pod',p.name,'players',(SELECT jsonb_agg(jsonb_build_object('id',pl.id,'name',pl."displayName") ORDER BY tp."rosterPosition") FROM "TeamPlayer" tp JOIN "Player" pl ON pl.id=tp."playerId" WHERE tp."teamId"=t.id)) ORDER BY t.id) FROM "Team" t JOIN "PodTeam" pt ON pt."teamId"=t.id JOIN "Pod" p ON p.id=pt."podId" WHERE t."tournamentId"='tournament-2026'),
'matches',(SELECT jsonb_agg(jsonb_build_object('id',m.id,'stage',m.stage,'status',m.status,'round',m."roundLabel",'date',m."scheduledAt",'a',m."homeTeamId",'b',m."awayTeamId",'winner',m."winningTeamId",'next',m."advancesToMatchId",'slot',m."advancesToSlot",'course',c.name,'snapshot',jsonb_build_object('version',m."officialResultSnapshot"->'version','winner',m."officialResultSnapshot"->'winningTeamId','summaries',m."officialResultSnapshot"->'teamSummaries','playedHoles',jsonb_array_length(m."officialResultSnapshot"->'holes'),'holeMeta',m."officialResultSnapshot"->'holeMeta','players',(SELECT jsonb_agg(jsonb_build_object('id',p->'playerId','teamId',p->'teamId','name',p->'playerName','tees',p->'teeName','gross',p->'grossByHole','strokes',p->'strokesByHole','net',p->'netByHole')) FROM jsonb_array_elements(m."officialResultSnapshot"->'players') p))) ORDER BY m.stage,m."roundLabel") FROM "Match" m LEFT JOIN "Course" c ON c.id=m."courseId" WHERE m."tournamentId"='tournament-2026')) AS archive
